import {NextResponse} from 'next/server';
import {z} from 'zod';
import {prisma} from '@/lib/db';
import {currentUser,unauthorized,forbidden,apiError} from '@/lib/server';
import {getFileUrl} from '@/lib/s3';
export const dynamic='force-dynamic';
export async function GET(_req:Request,{params}:{params:Promise<{id:string}>}){try{const user=await currentUser();if(!user)return unauthorized();const {id}=await params;const ticket=await prisma.ticket.findFirst({where:{id,...(user.role==='MUNICIPAL_ADMIN'?{}:{userId:user.id})},include:{uploads:true,events:{orderBy:{createdAt:'asc'}},user:{select:{name:true}}}});if(!ticket)return NextResponse.json({error:'Başvuru bulunamadı.'},{status:404});const photos=await Promise.all(ticket.uploads.map(async(f)=>({id:f.id,name:f.fileName,url:await getFileUrl(f.cloud_storage_path,f.contentType,f.isPublic)})));return NextResponse.json({...ticket,uploads:undefined,photos});}catch(e){return apiError(e);}}
export async function PATCH(req:Request,{params}:{params:Promise<{id:string}>}){try{const user=await currentUser();if(!user)return unauthorized();if(user.role!=='MUNICIPAL_ADMIN')return forbidden();const {id}=await params;const parsed=z.object({status:z.enum(['OPEN','IN_PROGRESS','RESOLVED','REJECTED']),adminResponse:z.string().trim().min(5).max(3000),expectedUpdatedAt:z.string().datetime()}).safeParse(await req.json());if(!parsed.success)return NextResponse.json({error:'Durum seçin ve en az 5 karakterli bir yanıt yazın. Sayfa eskiyse yenileyip tekrar deneyin.'},{status:400});const old=await prisma.ticket.findUnique({where:{id}});if(!old)return NextResponse.json({error:'Başvuru bulunamadı.'},{status:404});if(old.updatedAt.toISOString()!==parsed.data.expectedUpdatedAt)return NextResponse.json({error:'Bu başvuru başka bir işlemle güncellendi. Yazdığınız yanıt korunuyor; güncel durumu yükleyip yeniden değerlendirin.'},{status:409});const transitions:Record<string,string[]>={OPEN:['OPEN','IN_PROGRESS','REJECTED'],IN_PROGRESS:['IN_PROGRESS','RESOLVED','REJECTED'],RESOLVED:['RESOLVED'],REJECTED:['REJECTED']};if(!transitions[old.status]?.includes(parsed.data.status))return NextResponse.json({error:'Bu durum geçişi uygun değil. Alınan başvuruyu önce işlemde durumuna geçirin.'},{status:400});const saved=await prisma.$transaction(async(tx)=>{const changed=await tx.ticket.updateMany({where:{id,updatedAt:old.updatedAt},data:{status:parsed.data.status,adminResponse:parsed.data.adminResponse,updatedAt:new Date(Math.max(Date.now(),old.updatedAt.getTime()+1))}});if(changed.count!==1)return false;await tx.ticketEvent.create({data:{ticketId:id,status:parsed.data.status,message:parsed.data.adminResponse}});return true;});if(!saved)return NextResponse.json({error:'Bu başvuru başka bir işlemle güncellendi. Yazdığınız yanıt korunuyor; güncel durumu yükleyip yeniden değerlendirin.'},{status:409});return NextResponse.json({id});}catch(e){return apiError(e);}}
